from ..models import Sequential

def _check_pydot():
    # Check if pydot is installed and available
    try:
        import pydot
    except ImportError:
        raise ImportError("pydot is not installed. Please install it using `pip install pydot`.")

    # Check if pydot is available
    if not pydot:
        raise ImportError("pydot is not available. Please ensure it is installed and available.")

    # Check if pydot can create a graph
    try:
        pydot.Dot()
    except Exception as e:
        raise ImportError("pydot cannot create a graph. Error: {}".format(str(e)))

def create_model_graph(model, show_layer_names=False):
    _check_pydot()
    dot = pydot.Dot()
    dot.set('rankdir', 'TB')
    dot.set('concentrate', True)
    dot.set_node_defaults(shape='record')

    if show_layer_names:
        for layer in model.layers:
            dot.add_node(pydot.Node(str(layer.name), label=str(layer.name)))

